private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    if (bb == null) {
        throw new IllegalArgumentException("ByteBuffer cannot be null");
    }
    if (sb == null) {
        throw new IllegalArgumentException("StringBuilder cannot be null");
    }
    if (i < 0 || i >= bb.limit()) {
        throw new IllegalArgumentException("Index out of bounds: " + i);
    }

    int b0 = bb.get(i) & 0xFF;
    int numBytes;
    int codePoint;

    if ((b0 & 0x80) == 0) { // 1-byte ASCII
        numBytes = 1;
        codePoint = b0;
    } else if ((b0 & 0xE0) == 0xC0) { // 2-byte sequence
        numBytes = 2;
        if (i + 1 >= bb.limit()) {
            throw new IllegalArgumentException("Incomplete 2-byte UTF-8 sequence at index " + i);
        }
        int b1 = bb.get(i + 1) & 0xFF;
        if ((b1 & 0xC0) != 0x80) {
            throw new IllegalArgumentException("Invalid continuation byte at index " + (i + 1));
        }
        codePoint = ((b0 & 0x1F) << 6) | (b1 & 0x3F);
    } else if ((b0 & 0xF0) == 0xE0) { // 3-byte sequence
        numBytes = 3;
        if (i + 2 >= bb.limit()) {
            throw new IllegalArgumentException("Incomplete 3-byte UTF-8 sequence at index " + i);
        }
        int b1 = bb.get(i + 1) & 0xFF;
        int b2 = bb.get(i + 2) & 0xFF;
        if ((b1 & 0xC0) != 0x80 || (b2 & 0xC0) != 0x80) {
            throw new IllegalArgumentException("Invalid continuation byte in 3-byte sequence at index " + i);
        }
        codePoint = ((b0 & 0x0F) << 12) | ((b1 & 0x3F) << 6) | (b2 & 0x3F);
    } else if ((b0 & 0xF8) == 0xF0) { // 4-byte sequence
        numBytes = 4;
        if (i + 3 >= bb.limit()) {
            throw new IllegalArgumentException("Incomplete 4-byte UTF-8 sequence at index " + i);
        }
        int b1 = bb.get(i + 1) & 0xFF;
        int b2 = bb.get(i + 2) & 0xFF;
        int b3 = bb.get(i + 3) & 0xFF;
        if ((b1 & 0xC0) != 0x80 || (b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80) {
            throw new IllegalArgumentException("Invalid continuation byte in 4-byte sequence at index " + i);
        }
        codePoint = ((b0 & 0x07) << 18) | ((b1 & 0x3F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
    } else {
        throw new IllegalArgumentException("Invalid UTF-8 leading byte at index " + i);
    }

    if (codePoint > 0x10FFFF) {
        throw new IllegalArgumentException("Code point out of Unicode range: " + Integer.toHexString(codePoint));
    }

    if (codePoint <= 0xFFFF) {
        sb.append((char) codePoint);
    } else {
        // Surrogate pair
        int temp = codePoint - 0x10000;
        char high = (char) ((temp >> 10) + 0xD800);
        char low = (char) ((temp & 0x3FF) + 0xDC00);
        sb.append(high).append(low);
    }

    return i + numBytes;
}

int visitFrameStart(final int offset, final int numLocal, final int numStack) {
    // Validate arguments
    if (offset < 0) {
        throw new IllegalArgumentException("offset must be non-negative");
    }
    if (numLocal < 0) {
        throw new IllegalArgumentException("numLocal must be non-negative");
    }
    if (numStack < 0) {
        throw new IllegalArgumentException("numStack must be non-negative");
    }

    // Compute the required size for the frame array
    long total = (long) numLocal + (long) numStack + 3L; // 3 for offset, numLocal, numStack
    if (total > Integer.MAX_VALUE) {
        throw new IllegalArgumentException("frame size too large");
    }
    int size = (int) total;

    // Allocate and initialize the frame
    try {
        currentFrame = new int[size];
    } catch (NegativeArraySizeException e) {
        throw new IllegalArgumentException("invalid frame size", e);
    }
    currentFrame[0] = offset;
    currentFrame[1] = numLocal;
    currentFrame[2] = numStack;

    // Return the index of the next element to be written
    return 3;
}

private void enlarge(final int size) {
    if (size <= 0) {
        throw new IllegalArgumentException("Size must be positive");
    }
    int currentCapacity = (data == null) ? 0 : data.length;
    long newCapLong = (long) currentCapacity + size;
    int newCapacity;
    if (newCapLong > Integer.MAX_VALUE) {
        newCapacity = Integer.MAX_VALUE;
    } else {
        newCapacity = (int) newCapLong;
    }
    try {
        byte[] newData = new byte[newCapacity];
        if (data != null) {
            System.arraycopy(data, 0, newData, 0, data.length);
        }
        data = newData;
    } catch (OutOfMemoryError e) {
        throw new IllegalStateException("Unable to enlarge byte vector", e);
    }
}

