@Override
public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    if (target == null) {
        throw new IllegalArgumentException("Target graph cannot be null");
    }
    if (resultMap == null) {
        throw new IllegalArgumentException("Result map cannot be null");
    }
    java.util.List<V> partU = new java.util.ArrayList<>();
    java.util.List<V> partV = new java.util.ArrayList<>();
    for (java.util.Map.Entry<String,V> entry : resultMap.entrySet()) {
        String key = entry.getKey();
        V vertex = entry.getValue();
        if (key != null && key.startsWith("U")) {
            partU.add(vertex);
        } else if (key != null && key.startsWith("V")) {
            partV.add(vertex);
        }
    }
    if (partU.isEmpty() || partV.isEmpty()) {
        throw new IllegalArgumentException("Result map must contain vertices for both parts of bipartite graph");
    }
    // Ensure vertices are in the graph
    for (V u : partU) {
        try {
            target.addVertex(u);
        } catch (IllegalArgumentException e) {
            // ignore if already present
        }
    }
    for (V v : partV) {
        try {
            target.addVertex(v);
        } catch (IllegalArgumentException e) {
            // ignore if already present
        }
    }
    // Add edges to form a complete bipartite graph
    for (V u : partU) {
        for (V v : partV) {
            try {
                target.addEdge(u, v);
            } catch (IllegalArgumentException e) {
                // ignore duplicate edges or other issues
            }
        }
    }
}

protected int findByte(byte value, int pos) {
    // Ensure the buffer exists
    if (buffer == null) {
        throw new IllegalStateException("Buffer is null");
    }
    // Validate starting position
    if (pos < 0 || pos >= buffer.length) {
        throw new IllegalArgumentException("Starting position out of bounds: " + pos);
    }
    // Search for the byte value
    for (int i = pos; i < buffer.length; i++) {
        if (buffer[i] == value) {
            return i;
        }
    }
    // Not found
    return -1;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    if (buffer == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    int size = schema.getSerializedSize(message);
    if (size < 0) {
        throw new IllegalArgumentException("Serialized size cannot be negative");
    }

    // Write the length as a varint
    int tempSize = size;
    while (tempSize >= 0x80) {
        out.write((tempSize & 0x7F) | 0x80);
        tempSize >>>= 7;
    }
    out.write(tempSize);

    // Write the message itself
    schema.writeTo(out, message, buffer);

    return size;
}

