public Mappings diffStructure(String tableName, Mappings mappings) {
    if (tableName == null || tableName.isEmpty()) {
        throw new IllegalArgumentException("tableName cannot be null or empty");
    }
    if (mappings == null) {
        throw new IllegalArgumentException("mappings cannot be null");
    }
    try {
        // Retrieve the current index mapping for the given table.
        Mappings currentMappings = getCurrentMappings(tableName);
        if (currentMappings == null) {
            throw new IllegalStateException("Current mappings not found for table: " + tableName);
        }

        Mappings diff = new Mappings();
        java.util.Map<String, Object> currentProps = currentMappings.getProperties();
        java.util.Map<String, Object> historyProps = mappings.getProperties();

        for (java.util.Map.Entry<String, Object> entry : currentProps.entrySet()) {
            String field = entry.getKey();
            // Skip the _source configuration to avoid update conflicts.
            if ("_source".equals(field)) {
                continue;
            }
            // Add only fields that are not present in the history mapping.
            if (!historyProps.containsKey(field)) {
                diff.put(field, entry.getValue());
            }
        }
        return diff;
    } catch (Exception e) {
        throw new RuntimeException("Failed to compute diff structure for table: " + tableName, e);
    }
}

