    }
}

public long readLong(final int offset){
    if (offset < 0 || offset > b.length - 8) {
        throw new IllegalArgumentException("offset out of bounds");
    }
    int high = ((b[offset] & 0xFF) << 24) | ((b[offset + 1] & 0xFF) << 16) | ((b[offset + 2] & 0xFF) << 8) | (b[offset + 3] & 0xFF);
    int low = ((b[offset + 4] & 0xFF) << 24) | ((b[offset + 5] & 0xFF) << 16) | ((b[offset + 6] & 0xFF) << 8) | (b[offset + 7] & 0xFF);
    return ((long) high << 32) | (low & 0xFFFFFFFFL);
}

