        throw new IllegalArgumentException("message cannot be null");
    }
    if (clientWriters == null || clientWriters.isEmpty()) {
        return;
    }
    String telnetMessage = message + "\r\n";
    for (Writer writer : clientWriters) {
        if (writer == null) {
            continue;
        }
        try {
            writer.write(telnetMessage);
            writer.flush();
        } catch (IOException e) {
            // If a writer fails, we simply skip it. In a real implementation,
