public void removeFromTreeEdgeList() {
    try {
        // Remove from the first vertex's tree edge list
        if (vertex1 != null) {
            if (prev1 != null) {
                prev1.next1 = next1;
            } else {
                // this edge is the head of vertex1's list
                vertex1.treeEdgeListHead = next1;
            }
            if (next1 != null) {
                next1.prev1 = prev1;
            } else {
                // this edge is the tail of vertex1's list
                vertex1.treeEdgeListTail = prev1;
            }
        }

        // Remove from the second vertex's tree edge list
        if (vertex2 != null) {
            if (prev2 != null) {
                prev2.next2 = next2;
            } else {
                // this edge is the head of vertex2's list
                vertex2.treeEdgeListHead = next2;
            }
            if (next2 != null) {
                next2.prev2 = prev2;
            } else {
                // this edge is the tail of vertex2's list
                vertex2.treeEdgeListTail = prev2;
            }
        }

        // Clear this edge's own references
        prev1 = next1 = prev2 = next2 = null;
    } catch (Exception e) {
        throw new RuntimeException("Failed to remove edge from tree edge list", e);
    }
}

public static String findAndSubst(String key, Properties props) {
    if (props == null) {
        throw new IllegalArgumentException("Properties object cannot be null");
    }
    if (key == null) {
        throw new IllegalArgumentException("Key cannot be null");
    }
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    String result = value;
    java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)\\}");
    int maxDepth = 10;
    for (int depth = 0; depth < maxDepth; depth++) {
        java.util.regex.Matcher matcher = pattern.matcher(result);
        StringBuffer sb = new StringBuffer();
        boolean found = false;
        while (matcher.find()) {
            found = true;
            String varName = matcher.group(1);
            String replacement = props.getProperty(varName);
            if (replacement == null) {
                // keep the placeholder unchanged if no property found
                replacement = matcher.group(0);
            } else {
                // escape replacement for regex replacement
                replacement = java.util.regex.Matcher.quoteReplacement(replacement);
            }
            matcher.appendReplacement(sb, replacement);
        }
        matcher.appendTail(sb);
        String newResult = sb.toString();
        if (!found || newResult.equals(result)) {
            break;
        }
        result = newResult;
    }
    return result;
}

