    if (ignoreCase) {
        return str.regionMatches(true, strLen - suffixLen, suffix, 0, suffixLen);
    } else {
        return str.endsWith(suffix);
    }
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return new java.util.ArrayList<>();
    }
    // Remove leading '/' if present
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }
    if (rawPath.isEmpty()) {
        return new java.util.ArrayList<>();
    }
    String[] segments = rawPath.split("/", -1); // keep trailing empty segments
    java.util.List<PathSegmentImpl> result = new java.util.ArrayList<>(segments.length);
    for (String seg : segments) {
        String value = seg;
        if (decode) {
            try {
                java.net.URI temp = new java.net.URI(null, null, seg, null);
                value = temp.getPath();
            } catch (java.net.URISyntaxException e) {
                throw new IllegalArgumentException("Invalid percent-encoding in segment: " + seg, e);
            }
        }
        result.add(new PathSegmentImpl(value));
    }
    return result;
}

