private boolean containsAllFields(Fields fields) {
    if (fields == null) {
        throw new IllegalArgumentException("fields cannot be null");
    }
    if (properties == null) {
        return false;
    }
    try {
        java.lang.reflect.Method method = fields.getClass().getMethod("getFieldNames");
        Object result = method.invoke(fields);
        if (result instanceof java.util.Collection) {
            for (Object obj : (java.util.Collection<?>) result) {
                String name = obj.toString();
                if (!properties.containsKey(name)) {
                    return false;
                }
            }
            return true;
        } else {
            throw new IllegalArgumentException("getFieldNames() did not return a Collection");
        }
    } catch (NoSuchMethodException e) {
        if (fields instanceof java.lang.Iterable) {
            for (Object obj : (java.lang.Iterable<?>) fields) {
                String name = obj.toString();
                if (!properties.containsKey(name)) {
                    return false;
                }
            }
            return true;
        } else {
            throw new IllegalArgumentException("fields must provide getFieldNames() or be Iterable", e);
        }
    } catch (Exception e) {
        throw new RuntimeException("Error checking fields", e);
    }
}

