public String format(final LoggingEvent event){
    if (event == null) {
        throw new IllegalArgumentException("LoggingEvent cannot be null");
    }
    try {
        StringBuilder sb = new StringBuilder();
        // Format timestamp
        sb.append("[");
        sb.append(new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS")
                .format(new java.util.Date(event.getTimeStamp())));
        sb.append("] ");
        // Log level
        sb.append(event.getLevel().toString());
        // Thread name
        sb.append(" [");
        sb.append(event.getThreadName());
        sb.append("] ");
        // Logger name
        sb.append(event.getLoggerName());
        sb.append(" - ");
        // Message
        sb.append(event.getMessage());
        // Throwable information if available
        try {
            Object throwableInfo = event.getThrowableInformation();
            if (throwableInfo != null) {
                java.lang.Throwable t = (java.lang.Throwable) throwableInfo.getThrowable();
                if (t != null) {
                    sb.append(System.lineSeparator());
                    sb.append(t.toString());
                    for (StackTraceElement ste : t.getStackTrace()) {
                        sb.append(System.lineSeparator());
                        sb.append("\tat ").append(ste.toString());
                    }
                }
            }
        } catch (Exception ignored) {
            // If throwable information is not available, ignore
        }
        return sb.toString();
    } catch (Exception e) {
        // Return a simple error message if formatting fails
        return "Error formatting LoggingEvent: " + e.getMessage();
    }
}

