                case AbstractType.OBJECT:
                    int cpIndex = type.getIndex();
                    stackMapTableEntries.write((cpIndex >> 8) & 0xFF);
                    stackMapTableEntries.write(cpIndex & 0xFF);
                    break;
                case AbstractType.UNINITIALIZED:
                    int offset = type.getOffset();
                    stackMapTableEntries.write((offset >> 8) & 0xFF);
                    stackMapTableEntries.write(offset & 0xFF);
                    break;
                default:
                    // No additional data for other tags
                    break;
            }
        }
    } catch (IOException e) {
        throw new RuntimeException("Failed to write abstract types to stackMapTableEntries", e);
    }
}

public void readFrom(final InputStream in) throws IOException {
    if (in == null) {
        throw new IllegalArgumentException("InputStream cannot be null");
    }
    // Read all bytes from the input stream into a temporary buffer
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    byte[] temp = new byte[8192];
    int read;
    while ((read = in.read(temp)) != -1) {
        baos.write(temp, 0, read);
    }
    // Replace the existing buffer with the new data
    this.buffer = baos.toByteArray();
    // Reset the read pointer to the start of the buffer
    this.readPointer = 0;
}

