@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Ensure the target type is Character or char
    if (type != Character.class && type != char.class) {
        throw new IllegalArgumentException("Target type must be java.lang.Character or char");
    }
    // Null values are returned as null
    if (value == null) {
        return null;
    }
    // If already a Character, return it directly
    if (value instanceof Character) {
        return value;
    }
    // If the value is a String, it must be a single character
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0);
        } else {
            throw new IllegalArgumentException("String length must be 1 to convert to Character");
        }
    }
    // If the value is a Number, cast its int value to a char
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        return (char) intVal;
    }
    // Unsupported conversion
    throw new IllegalArgumentException("Cannot convert value of type " + value.getClass().getName() + " to java.lang.Character");
}

