public final byte[] toByteArray() {
    // If there are no buffers, return an empty array
    if (buffers == null || buffers.isEmpty()) {
        return new byte[0];
    }

    // Calculate the total number of bytes that will be copied
    int totalSize = 0;
    for (ByteBuffer buf : buffers) {
        if (buf != null) {
            totalSize += buf.remaining();
        }
    }

    // Allocate the result array
    byte[] result = new byte[totalSize];
    int offset = 0;

    // Copy each buffer's remaining bytes into the result array
    for (ByteBuffer buf : buffers) {
        if (buf != null) {
            // Duplicate the buffer so that the original position is not altered
            ByteBuffer dup = buf.duplicate();
            int len = dup.remaining();
            dup.get(result, offset, len);
            offset += len;
        }
    }

    return result;
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= len) {
                // trailing backslash, keep it
                sb.append('\\');
                break;
            }
            char next = str.charAt(i + 1);
            // Handle escaped backslash
            if (next == '\\') {
                sb.append('\\');
                i++; // skip the next backslash
                continue;
            }
            switch (next) {
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case '\'':
                    sb.append('\'');
                    i++;
                    break;
                case '\"':
                    sb.append('\"');
                    i++;
                    break;
                case 'u':
                    // Unicode escape: \uXXXX
                    if (i + 5 >= len) {
                        throw new Exception("Invalid unicode escape sequence at position " + i);
                    }
                    String hex = str.substring(i + 2, i + 6);
                    try {
                        int code = Integer.parseInt(hex, 16);
                        sb.append((char) code);
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid unicode escape sequence '\\u" + hex + "' at position " + i);
                    }
                    i += 5; // skip \uXXXX
                    break;
                default:
                    // Octal escape: up to 3 octal digits (0-7)
                    if (next >= '0' && next <= '7') {
                        int j = i + 1;
                        int end = Math.min(j + 3, len);
                        int value = 0;
                        while (j < end) {
                            char d = str.charAt(j);
                            if (d < '0' || d > '7') {
                                break;
                            }
                            value = (value << 3) + (d - '0');
                            j++;
                        }
                        sb.append((char) value);
                        i = j - 1; // adjust for loop increment
                    } else {
                        // Unrecognized escape, keep as is
                        sb.append(next);
                        i++;
                    }
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

