private static Object copyArrayGrow1(final Object array, final Class<?> newArrayComponentType) {
    if (array == null) {
        if (newArrayComponentType == null) {
            throw new IllegalArgumentException("Both array and newArrayComponentType are null");
        }
        return java.lang.reflect.Array.newInstance(newArrayComponentType, 1);
    }
    Class<?> arrayClass = array.getClass();
    if (!arrayClass.isArray()) {
        throw new IllegalArgumentException("Provided object is not an array");
    }
    Class<?> componentType = arrayClass.getComponentType();
    int oldLen = java.lang.reflect.Array.getLength(array);
    Object newArray = java.lang.reflect.Array.newInstance(componentType, oldLen + 1);
    System.arraycopy(array, 0, newArray, 0, oldLen);
    return newArray;
}

private int computeBinaryLog(int n){
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    // Integer.numberOfLeadingZeros returns the number of zero bits preceding the highest-order (leftmost) one-bit.
    // For a positive integer n, floor(log2(n)) = 31 - numberOfLeadingZeros(n).
    // Adding 1 gives the desired result.
    return 32 - Integer.numberOfLeadingZeros(n);
}

private Set<V> intersection(Set<V> set1, Set<V> set2) {
    if (set1 == null || set2 == null) {
        throw new IllegalArgumentException("Input sets must not be null");
    }
    // Choose the smaller set to iterate over for efficiency
    Set<V> smaller = set1.size() <= set2.size() ? set1 : set2;
    Set<V> larger = set1.size() > set2.size() ? set1 : set2;
    Set<V> result = new HashSet<>(Math.min(set1.size(), set2.size()));
    for (V element : smaller) {
        if (larger.contains(element)) {
            result.add(element);
        }
    }
    return result;
}

