private int removeUnusedNodesRecursive(Category node) {
    int count = 0;
    if (node == null) {
        return 0;
    }
    List<Category> children = node.getChildren();
    if (children == null) {
        return 0;
    }
    Iterator<Category> it = children.iterator();
    while (it.hasNext()) {
        Category child = it.next();
        if (!child.isActive()) {
            it.remove();
            count++;
        } else {
            count += removeUnusedNodesRecursive(child);
        }
    }
    return count;
}

