final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Validate classFileBuffer and constantPoolEntryIndex
    if (classFileBuffer == null) {
        throw new IllegalArgumentException("classFileBuffer is null");
    }
    if (constantPoolEntryIndex <= 0) {
        throw new IllegalArgumentException("constantPoolEntryIndex must be > 0");
    }
    // The constant pool count is stored at offset 8-9
    if (classFileBuffer.length < 10) {
        throw new IllegalArgumentException("classFileBuffer too short to contain constant pool");
    }
    final int constantPoolCount = ((classFileBuffer[8] & 0xFF) << 8) | (classFileBuffer[9] & 0xFF);
    if (constantPoolEntryIndex >= constantPoolCount) {
        throw new IllegalArgumentException("constantPoolEntryIndex out of bounds");
    }

    // Find the offset of the requested constant pool entry
    int offset = 10; // start of constant pool entries
    try {
        for (int i = 1; i < constantPoolEntryIndex; i++) {
            int tag = classFileBuffer[offset] & 0xFF;
            offset++;
            switch (tag) {
                case 1: // CONSTANT_Utf8
                    int len = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
                    offset += 2 + len;
                    break;
                case 3: // CONSTANT_Integer
                case 4: // CONSTANT_Float
                    offset += 4;
                    break;
                case 5: // CONSTANT_Long
                case 6: // CONSTANT_Double
                    offset += 8;
                    i++; // these take up two entries
                    break;
                case 7: // CONSTANT_Class
                case 8: // CONSTANT_String
                    offset += 2;
                    break;
                case 9: // CONSTANT_Fieldref
                case 10: // CONSTANT_Methodref
                case 11: // CONSTANT_InterfaceMethodref
                case 12: // CONSTANT_NameAndType
                    offset += 4;
                    break;
                case 15: // CONSTANT_MethodHandle
                    offset += 3;
                    break;
                case 16: // CONSTANT_MethodType
                    offset += 2;
                    break;
                case 18: // CONSTANT_InvokeDynamic
                    offset += 4;
                    break;
                default:
                    throw new IllegalArgumentException("Invalid constant pool tag: " + tag);
            }
        }

        // Now offset points to the target entry
        int tag = classFileBuffer[offset] & 0xFF;
        if (tag != 1) {
            throw new IllegalArgumentException("Requested constant pool entry is not a CONSTANT_Utf8");
        }
        offset++;
        int length = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
        offset += 2;
        if (length > charBuffer.length) {
            throw new IllegalArgumentException("Provided charBuffer is too small for the UTF-8 string");
        }
        if (offset + length > classFileBuffer.length) {
            throw new IllegalArgumentException("classFileBuffer does not contain enough bytes for the UTF-8 string");
        }
        byte[] bytes = new byte[length];
        System.arraycopy(classFileBuffer, offset, bytes, 0, length);
        String result = new String(bytes, java.nio.charset.StandardCharsets.UTF_8);
        char[] chars = result.toCharArray();
        System.arraycopy(chars, 0, charBuffer, 0, chars.length);
        return result;
    } catch (ArrayIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("classFileBuffer is malformed or too short", e);
    }
}

