public static long factorial(int n){
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    java.math.BigInteger result = java.math.BigInteger.ONE;
    java.math.BigInteger maxLong = java.math.BigInteger.valueOf(Long.MAX_VALUE);
    for (int i = 2; i <= n; i++) {
        result = result.multiply(java.math.BigInteger.valueOf(i));
        if (result.compareTo(maxLong) > 0) {
            throw new ArithmeticException("Factorial result overflows long");
        }
    }
    return result.longValue();
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate must not be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("Start and stop nodes must not be null");
    }

    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

    // If the start node already satisfies the predicate, return it immediately
    if (predicate.test(circ.getNode())) {
        return circ;
    }

    // If the start node is the stop node, return the circulator pointing to it
    if (circ.getNode().equals(stop)) {
        return circ;
    }

    // Traverse the outer face until we reach the stop node or find a node that satisfies the predicate
    while (!circ.getNode().equals(stop)) {
        circ.next(); // move to the next node in the specified direction
        if (predicate.test(circ.getNode())) {
            return circ;
        }
    }

    // At this point, circ.getNode() == stop
    return circ;
}

