        throw new IllegalArgumentException("files array cannot be null");
    }
    for (int i = files.length - 1; i >= 0; i--) {
        InputStream file = files[i];
        if (file == null) {
            throw new IllegalArgumentException("file at index " + i + " is null");
        }
        // Add the file to the internal collection in reverse order
        this.filesList.add(file);
    }
}

private void check(String modelName) throws IllegalStateException {
    if (modelName == null || modelName.isEmpty()) {
        throw new IllegalArgumentException("modelName cannot be null or empty");
    }
    try {
        java.util.List<Integer> indices = getShardingKeyIndices(modelName);
        if (indices == null || indices.isEmpty()) {
            return; // No sharding keys, considered continuous
        }
        java.util.List<Integer> sorted = new java.util.ArrayList<>(indices);
        java.util.Collections.sort(sorted);
        int expected = sorted.get(0);
        for (int idx : sorted) {
            if (idx != expected) {
                throw new IllegalStateException("Sharding key indices are not continuous for model: " + modelName);
            }
            expected++;
        }
    } catch (IllegalStateException e) {
        throw e;
    } catch (Exception e) {
        throw new IllegalStateException("Error checking sharding key indices for model: " + modelName, e);
    }
}

public byte readByte() throws IOException {
    if (bufferPos >= bufferLimit) {
        bufferLimit = in.read(buffer);
        if (bufferLimit == -1) {
            throw new IOException("No more data available");
        }
        bufferPos = 0;
    }
    return buffer[bufferPos++];
}

@Override public Action inspect(AtmosphereResource r) {
    if (r == null) {
        throw new IllegalArgumentException("AtmosphereResource cannot be null");
    }
    try {
        // Determine the transport type of the resource
        String transport = r.getTransport();
        if (transport == null) {
            // No transport information; nothing to suspend
            return Action.CONTINUE;
        }

        // Suspend the resource for transports that support suspension
        // (e.g., long-polling, SSE, etc.). WebSocket is typically not suspended.
        if (!"websocket".equalsIgnoreCase(transport)) {
            r.suspend();
        }
    } catch (Exception e) {
        // Wrap any exception in a runtime exception to signal failure
        throw new RuntimeException("Failed to inspect AtmosphereResource", e);
    }
    return Action.CONTINUE;
}

public double vertexWeight(Set<V> v) {
    if (v == null) {
        throw new IllegalArgumentException("Vertex set cannot be null");
    }
    double totalWeight = 0.0;
    try {
        for (V vertex : v) {
            if (vertex == null) {
                continue;
            }
            // Assume a method getIncomingEdges that returns a collection of edges for a vertex
            Collection<Edge<V>> incoming = getIncomingEdges(vertex);
            if (incoming != null) {
                for (Edge<V> e : incoming) {
                    if (e != null) {
                        totalWeight += e.getWeight();
                    }
                }
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Error computing vertex weight", e);
    }
    return totalWeight;
}

public int compare(Object aObj1, Object aObj2) {
    try {
        if (aObj1 == aObj2) {
            return 0;
        }
        if (aObj1 == null) {
            return -1;
        }
        if (aObj2 == null) {
            return 1;
        }
        if (aObj1 instanceof Comparable && aObj2 instanceof Comparable) {
            if (aObj1.getClass() == aObj2.getClass()) {
                return ((Comparable) aObj1).compareTo(aObj2);
            }
        }
        String s1 = aObj1.toString();
        String s2 = aObj2.toString();
        if (s1 == null && s2 == null) {
            return 0;
        }
        if (s1 == null) {
            return -1;
        }
        if (s2 == null) {
            return 1;
        }
        return s1.compareTo(s2);
    } catch (Exception e) {
        throw new IllegalArgumentException("Comparison failed", e);
    }
}

public void removeAppender(String name) {
    if (name == null || name.trim().isEmpty()) {
        throw new IllegalArgumentException("Appender name must not be null or empty");
    }
    try {
        if (appenders == null) {
            throw new IllegalStateException("Appender list is not initialized");
        }
        java.util.Iterator<Appender> it = appenders.iterator();
        boolean removed = false;
        while (it.hasNext()) {
            Appender a = it.next();
            if (name.equals(a.getName())) {
                it.remove();
                removed = true;
                break;
            }
        }
        if (!removed) {
            throw new java.util.NoSuchElementException("No appender found with name: " + name);
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to remove appender: " + name, e);
    }
}

public int appendLoopOnAppenders(LoggingEvent event) {
    if (event == null) {
        throw new IllegalArgumentException("LoggingEvent cannot be null");
    }
    int count = 0;
    Enumeration<?> e = getAllAppenders();
    if (e == null) {
        return count;
    }
    while (e.hasMoreElements()) {
        Object obj = e.nextElement();
        if (obj instanceof Appender) {
            Appender appender = (Appender) obj;
            if (appender != null) {
                try {
                    appender.doAppend(event);
                    count++;
                } catch (Exception ex) {
                    throw new RuntimeException("Error appending to appender: " + appender, ex);
                }
            }
        }
    }
    return count;
}

