protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        throw new IllegalArgumentException("Tour must contain at least one edge");
    }
    java.util.Map<V, java.util.List<E>> adjacency = new java.util.HashMap<>();
    for (E e : tour) {
        V source = graph.getEdgeSource(e);
        V target = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(source, k -> new java.util.ArrayList<>()).add(e);
        adjacency.computeIfAbsent(target, k -> new java.util.ArrayList<>()).add(e);
    }
    V start;
    if (graph.isDirected()) {
        E first = tour.iterator().next();
        start = graph.getEdgeSource(first);
    } else {
        start = adjacency.keySet().iterator().next();
    }
    java.util.List<E> orderedEdges = new java.util.ArrayList<>(tour.size());
    java.util.Set<E> remaining = new java.util.HashSet<>(tour);
    V current = start;
    while (!remaining.isEmpty()) {
        java.util.List<E> edges = adjacency.get(current);
        if (edges == null) {
            throw new IllegalArgumentException("Tour does not form a continuous path");
        }
        E chosen = null;
        for (E e : edges) {
            if (!remaining.contains(e)) {
                continue;
            }
            if (graph.isDirected() && !graph.getEdgeSource(e).equals(current)) {
                continue;
            }
            chosen = e;
            break;
        }
        if (chosen == null) {
            throw new IllegalArgumentException("Tour does not form a continuous path");
        }
        orderedEdges.add(chosen);
        remaining.remove(chosen);
        V next = graph.getEdgeSource(chosen).equals(current) ? graph.getEdgeTarget(chosen) : graph.getEdgeSource(chosen);
        current = next;
    }
    if (!current.equals(start)) {
        throw new IllegalArgumentException("Tour does not form a cycle");
    }
    double weight = 0.0;
    for (E e : orderedEdges) {
        weight += graph.getEdgeWeight(e);
    }
    return new org.jgrapht.graph.GraphWalk<>(graph, start, start, orderedEdges, weight);
}

