int addConstantNameAndType(final String name,final String descriptor){
    if(name==null||descriptor==null){
        throw new IllegalArgumentException("name and descriptor must not be null");
    }
    try{
        String key=name+'\0'+descriptor;
        Integer existing=nameAndTypeMap.get(key);
        if(existing!=null){
            return existing;
        }
        int nameIndex=utf8Map.computeIfAbsent(name, n->{
            int idx=constantPool.size();
            constantPool.add(n);
            return idx;
        });
        int descriptorIndex=utf8Map.computeIfAbsent(descriptor, d->{
            int idx=constantPool.size();
            constantPool.add(d);
            return idx;
        });
        int index=constantPool.size();
        constantPool.add(name+":"+descriptor);
        nameAndTypeMap.put(key,index);
        return index;
    }catch(Exception e){
        throw new RuntimeException("Failed to add CONSTANT_NameAndType_info",e);
    }
}

private String unescapeId(String input){
    if (input == null) {
        throw new IllegalArgumentException("input cannot be null");
    }
    StringBuilder sb = new StringBuilder();
    int len = input.length();
    for (int i = 0; i < len; i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            if (i + 1 >= len) {
                throw new IllegalArgumentException("Trailing backslash in input");
            }
            char next = input.charAt(++i);
            switch (next) {
                case 'n': sb.append('\n'); break;
                case 't': sb.append('\t'); break;
                case 'r': sb.append('\r'); break;
                case 'b': sb.append('\b'); break;
                case 'f': sb.append('\f'); break;
                case 'v': sb.append('\u000B'); break; // vertical tab
                case '\\': sb.append('\\'); break;
                case '"': sb.append('\"'); break;
                case '\'': sb.append('\''); break;
                case 'x':
                    if (i + 2 >= len) {
                        throw new IllegalArgumentException("Incomplete hex escape");
                    }
                    String hex = input.substring(i + 1, i + 3);
                    try {
                        int value = Integer.parseInt(hex, 16);
                        sb.append((char) value);
                    } catch (NumberFormatException e) {
                        throw new IllegalArgumentException("Invalid hex escape: \\" + hex);
                    }
                    i += 2;
                    break;
                case 'u':
                    if (i + 4 >= len) {
                        throw new IllegalArgumentException("Incomplete unicode escape");
                    }
                    String uni = input.substring(i + 1, i + 5);
                    try {
                        int value = Integer.parseInt(uni, 16);
                        sb.append((char) value);
                    } catch (NumberFormatException e) {
                        throw new IllegalArgumentException("Invalid unicode escape: \\" + uni);
                    }
                    i += 4;
                    break;
                default:
                    sb.append(next);
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

public static String[] concatenateStringArrays(String[] array1, String[] array2) {
    if (array1 == null && array2 == null) {
        return null;
    }
    if (array1 == null) {
        return array2.clone();
    }
    if (array2 == null) {
        return array1.clone();
    }
    String[] result = new String[array1.length + array2.length];
    System.arraycopy(array1, 0, result, 0, array1.length);
    System.arraycopy(array2, 0, result, array1.length, array2.length);
    return result;
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null) {
        throw new IllegalArgumentException("Buckets and labels must not be null");
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("minLabel out of bounds");
    }
    if (minLabel == 0) {
        // Nothing to move; the bucket is already the target.
        return;
    }
    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null) {
        throw new IllegalStateException("Source bucket is null");
    }
    if (source.isEmpty()) {
        return;
    }
    Set<Integer> target = bucketsByLabel.get(0);
    if (target == null) {
        throw new IllegalStateException("Target bucket 0 is null");
    }
    for (Integer v : source) {
        target.add(v);
        labels.set(v, 0);
    }
    source.clear();
}

public static String[] addStringToArray(String[] array, String str) {
    // Determine the size of the new array
    int newSize = (array == null ? 0 : array.length) + 1;
    // Create the new array
    String[] result = new String[newSize];
    // Copy existing elements if any
    if (array != null && array.length > 0) {
        System.arraycopy(array, 0, result, 0, array.length);
    }
    // Append the new string
    result[newSize - 1] = str;
    return result;
}

public static int countOccurrencesOf(String str, String sub) {
    if (str == null || sub == null) {
        return 0;
    }
    if (sub.isEmpty() || sub.length() > str.length()) {
        return 0;
    }
    int count = 0;
    int index = 0;
    while ((index = str.indexOf(sub, index)) != -1) {
        count++;
        index++; // allow overlapping matches
    }
    return count;
}

