private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    ListNodeImpl<E> prev = node.prev;
    ListNodeImpl<E> next = node.next;

    if (prev != null) {
        prev.next = next;
    } else {
        // node was head
        head = next;
    }

    if (next != null) {
        next.prev = prev;
    } else {
        // node was tail
        tail = prev;
    }

    // Detach node
    node.prev = null;
    node.next = null;

    size--;
    return true;
}

public java.util.List<SequenceRange> buildSequenceRanges() {
    try {
        java.util.List<SequenceRange> ranges = new java.util.ArrayList<>();
        if (currentProfiles == null) {
            return ranges;
        }
        for (Profile profile : currentProfiles) {
            if (profile == null) continue;
            java.util.List<Segment> segments = profile.getSegments();
            if (segments == null) continue;
            for (Segment segment : segments) {
                if (segment == null) continue;
                java.util.List<Snapshot> snapshots = segment.getSnapshots();
                if (snapshots == null) continue;
                for (Snapshot snapshot : snapshots) {
                    if (snapshot == null) continue;
                    java.util.List<Search> searches = snapshot.getSearches();
                    if (searches == null) continue;
                    for (Search search : searches) {
                        if (search == null) continue;
                        int start = search.getStart();
                        int end = search.getEnd();
                        ranges.add(new SequenceRange(start, end));
                    }
                }
            }
        }
        return ranges;
    } catch (Exception e) {
        throw new RuntimeException("Error building sequence ranges", e);
    }
}

