public static String stripFilenameExtension(String path){
    if (path == null || path.isEmpty()) {
        return null;
    }
    // Find last file separator
    int sepIndex = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    // Find last dot
    int dotIndex = path.lastIndexOf('.');
    // No dot or dot before separator or dot is last char -> no extension
    if (dotIndex == -1 || dotIndex <= sepIndex || dotIndex == path.length() - 1) {
        return null;
    }
    // Handle hidden files like ".bashrc" (no extension)
    if (dotIndex == 0 && sepIndex == -1) {
        return null;
    }
    return path.substring(0, dotIndex);
}

