private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null) {
        throw new IllegalArgumentException("bounds cannot be null");
    }
    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        suffix.add(0);
    }
    long running = 0;
    for (int i = n - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        if (val == null) {
            throw new IllegalArgumentException("bounds contains null at index " + i);
        }
        running += val;
        suffix.set(i, (int) running);
    }
    return new Pair<>(suffix, running);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array must not be null");
    }
    if (from < 0 || to >= arr.length || from > to) {
        throw new IllegalArgumentException("Invalid range: from=" + from + ", to=" + to + ", length=" + arr.length);
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        throw new IllegalArgumentException("Source list cannot be null");
    }
    if (list == this) {
        throw new IllegalArgumentException("Cannot move nodes from the same list");
    }
    java.util.ArrayList<ListNode<E>> temp = new java.util.ArrayList<>();
    while (!list.isEmpty()) {
        ListNode<E> node = list.getFirst();
        list.removeListNode(node);
        temp.add(node);
    }
    try {
        for (ListNode<E> node : temp) {
            this.addListNode(node);
        }
    } catch (RuntimeException e) {
        for (int i = temp.size() - 1; i >= 0; i--) {
            list.addListNode(temp.get(i));
        }
        throw e;
    }
}

