public ByteVector putInt(final int intValue){
    try {
        // Ensure there is enough space for 4 bytes
        if (buffer == null) {
            buffer = new byte[4];
        }
        if (pos + 4 > buffer.length) {
            int newSize = Math.max(buffer.length * 2, pos + 4);
            byte[] newBuffer = new byte[newSize];
            System.arraycopy(buffer, 0, newBuffer, 0, buffer.length);
            buffer = newBuffer;
        }
        // Write the int in big‑endian order
        buffer[pos++] = (byte)(intValue >> 24);
        buffer[pos++] = (byte)(intValue >> 16);
        buffer[pos++] = (byte)(intValue >> 8);
        buffer[pos++] = (byte)intValue;
        return this;
    } catch (Exception e) {
        throw new RuntimeException("Failed to put int into ByteVector", e);
    }
}

