private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null");
    }
    if (vertices == null) {
        throw new IllegalArgumentException("Vertices set must not be null");
    }
    // An empty set or a single vertex is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }
    try {
        for (V v1 : vertices) {
            for (V v2 : vertices) {
                if (!v1.equals(v2) && !graph.containsEdge(v1, v2)) {
                    return false;
                }
            }
        }
    } catch (IllegalArgumentException e) {
        // One of the vertices is not part of the graph or other illegal argument
        return false;
    } catch (Exception e) {
        // Unexpected exception during graph traversal
        throw new RuntimeException("Error while checking clique", e);
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
