    for (K key : keys) {
        if (key == null) {
            throw new IllegalArgumentException("key cannot be null");
        }
        Integer intKey;
        try {
            intKey = (Integer) key;
        } catch (ClassCastException e) {
            throw new IllegalArgumentException("key is not an Integer", e);
        }
        Integer maxLower = null;
        for (K other : keys) {
            if (other == null) {
                continue;
            }
            Integer intOther;
            try {
                intOther = (Integer) other;
            } catch (ClassCastException e) {
                continue; // skip non-integer values
            }
            if (intOther < intKey) {
                if (maxLower == null || intOther > maxLower) {
                    maxLower = intOther;
                }
            }
        }
        lowerBounds.add(maxLower);
    }
    return lowerBounds;
}

private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }
    final int len = descriptor.length();
    if (len == 0) {
        throw new IllegalArgumentException("Descriptor cannot be empty");
    }
    int i = 0;
    try {
        if (descriptor.charAt(0) == '(') {
            // Method descriptor: pop argument types
            i = 1;
            while (i < len && descriptor.charAt(i) != ')') {
                int start = i;
                // Skip array brackets
                while (i < len && descriptor.charAt(i) == '[') {
                    i++;
                }
                if (i >= len) {
                    throw new IllegalArgumentException("Invalid descriptor: unexpected end");
                }
                char c = descriptor.charAt(i);
                if (c == 'L') {
                    // Object type: find terminating ';'
                    int semicolon = descriptor.indexOf(';', i);
                    if (semicolon == -1) {
                        throw new IllegalArgumentException("Invalid descriptor: missing ';' for object type");
                    }
                    i = semicolon + 1;
                } else {
                    // Primitive type: single character
                    i++;
                }
                String typeDesc = descriptor.substring(start, i);
                if (!typeDesc.equals("V")) {
                    outputFrameStack.pop();
                }
            }
            // Skip ')'
            if (i >= len || descriptor.charAt(i) != ')') {
                throw new IllegalArgumentException("Invalid descriptor: missing closing parenthesis");
            }
            i++; // skip ')'
            // Skip return type (do not pop)
            if (i < len) {
                // Skip array brackets
                while (i < len && descriptor.charAt(i) == '[') {
                    i++;
                }
                if (i >= len) {
                    throw new IllegalArgumentException("Invalid descriptor: unexpected end after return type");
                }
                char c = descriptor.charAt(i);
                if (c == 'L') {
                    int semicolon = descriptor.indexOf(';', i);
                    if (semicolon == -1) {
                        throw new IllegalArgumentException("Invalid descriptor: missing ';' for return object type");
                    }
                    i = semicolon + 1;
                } else {
                    i++;
                }
                // No pop for return type
            }
        } else {
            // Single type descriptor
            int start = i;
            while (i < len && descriptor.charAt(i) == '[') {
                i++;
            }
            if (i >= len) {
                throw new IllegalArgumentException("Invalid descriptor: unexpected end");
            }
            char c = descriptor.charAt(i);
            if (c == 'L') {
                int semicolon = descriptor.indexOf(';', i);
                if (semicolon == -1) {
                    throw new IllegalArgumentException("Invalid descriptor: missing ';' for object type");
                }
                i = semicolon + 1;
            } else {
                i++;
            }
            String typeDesc = descriptor.substring(start, i);
            if (!typeDesc.equals("V")) {
                outputFrameStack.pop();
            }
        }
    } catch (java.util.EmptyStackException e) {
        throw new IllegalStateException("Output frame stack underflow while popping type from descriptor: " + descriptor, e);
    }
}

