public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath must not be null");
    }
    // Trim any trailing spaces
    path = path.trim();
    relativePath = relativePath.trim();
    if (path.isEmpty()) {
        throw new IllegalArgumentException("Path must not be empty");
    }
    // Determine if path is absolute
    boolean isAbsolute = path.startsWith("/");
    // Split base path into components
    String[] baseParts = path.split("/");
    // If path ends with a slash, treat it as a directory; otherwise treat last part as file and remove it
    int baseLength = baseParts.length;
    if (!path.endsWith("/")) {
        // Remove the last component (file name)
        baseLength = baseParts.length - 1;
    }
    // Use a dynamic list to hold the path components
    java.util.List<String> components = new java.util.ArrayList<>();
    for (int i = 0; i < baseLength; i++) {
        if (!baseParts[i].isEmpty()) {
            components.add(baseParts[i]);
        }
    }
    // Process relative path components
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            // Skip
            continue;
        } else if (part.equals("..")) {
            if (!components.isEmpty()) {
                components.remove(components.size() - 1);
            }
        } else {
            components.add(part);
        }
    }
    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }
    for (int i = 0; i < components.size(); i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(components.get(i));
    }
    // If the original path ended with a slash and the result is empty, preserve the slash
    if (path.endsWith("/") && result.length() == 0) {
        result.append("/");
    }
    return result.toString();
}

