public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (str == null) {
        throw new IllegalArgumentException("The original string (or StringBuilder) must not be null.");
    }
    if (substring == null) {
        throw new IllegalArgumentException("The substring to match must not be null.");
    }
    int strLen = str.length();
    int subLen = substring.length();
    if (index < 0 || index > strLen) {
        throw new IndexOutOfBoundsException("Index " + index + " is out of bounds for string of length " + strLen + ".");
    }
    if (index + subLen > strLen) {
        return false; // Not enough characters to match the substring
    }
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

protected void append(LoggingEvent event) {
    if (event == null) {
        throw new IllegalArgumentException("LoggingEvent cannot be null");
    }

    String message;
    try {
        message = event.getFormattedMessage();
    } catch (Exception e) {
        // If message extraction fails, use an empty string
        message = "";
    }
    if (message == null) {
        message = "";
    }

    // If there are no connected clients, nothing to do
    if (clientWriters == null || clientWriters.isEmpty()) {
        return;
    }

    // Iterate over the connected clients and send the message
    for (java.util.Iterator<PrintWriter> it = clientWriters.iterator(); it.hasNext(); ) {
        PrintWriter writer = it.next();
        try {
            writer.println(message);
            writer.flush();
        } catch (java.io.IOException e) {
            // Remove the writer if it fails to write
            it.remove();
            // Optionally log the error (uncomment if a logger is available)
            // logger.error("Failed to write to client, removing writer", e);
        }
    }
}

