public int readTag() throws IOException {
    int result = 0;
    int shift = 0;
    while (shift < 32) {
        int b = input.read();
        if (b == -1) {
            if (shift == 0) {
                return 0; // EOF reached before any bytes read
            } else {
                throw new IOException("Truncated varint");
            }
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            if (result == 0) {
                throw new IOException("Invalid tag: 0");
            }
            return result;
        }
        shift += 7;
    }
    throw new IOException("Varint too long");
}

