        throw new IllegalArgumentException("file must not be null");
    }
    if (!file.exists() || !file.isFile()) {
        throw new java.io.FileNotFoundException("File not found: " + file);
    }

    // Assume there is an existing method that parses all snapshots from the file.
    List<ThreadSnapshot> allSnapshots = parseFromFile(file);

    if (timeRanges == null || timeRanges.isEmpty()) {
        return allSnapshots;
    }

    List<ThreadSnapshot> result = new ArrayList<>();
    for (ThreadSnapshot snapshot : allSnapshots) {
        long ts = snapshot.getTimestamp();
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (range == null) {
                continue;
            }
            long start = range.getStartTime();
            long end = range.getEndTime();
            if (start > end) {
                continue;
            }
            if (ts >= start && ts <= end) {
                result.add(snapshot);
                break; // snapshot matched a range, no need to check further ranges
            }
        }
    }
    return result;
}
